def parse_csv(text):
    lines = text.splitlines()
    if not lines:
        return []

    header_line = lines[0]
    header = []
    current_field = []
    in_quotes = False
    i = 0

    while i < len(header_line):
        char = header_line[i]
        if char == '"':
            if in_quotes and i + 1 < len(header_line) and header_line[i+1] == '"':
                current_field.append('"')
                i += 1
            else:
                in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            header.append(''.join(current_field))
            current_field = []
        else:
            current_field.append(char)
        i += 1

    header.append(''.join(current_field))

    result = []
    for line in lines[1:]:
        if not line.strip():
            continue

        row = []
        current_field = []
        in_quotes = False
        i = 0

        while i < len(line):
            char = line[i]
            if char == '"':
                if in_quotes and i + 1 < len(line) and line[i+1] == '"':
                    current_field.append('"')
                    i += 1
                else:
                    in_quotes = not in_quotes
            elif char == ',' and not in_quotes:
                row.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)
            i += 1

        row.append(''.join(current_field))

        if len(row) == len(header):
            result.append(dict(zip(header, row)))

    return result
```

