def normalize(path):
    if not path:
        return '.'

    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if is_absolute:
        if not stack:
            return '/'
        return '/' + '/'.join(stack)
    else:
        if not stack:
            return '.'
        return '/'.join(stack)
```

