def deep_get(obj, path, default=None):
    current = obj
    for segment in path:
        if isinstance(current, dict):
            if segment not in current:
                return default
            current = current[segment]
        elif isinstance(current, list):
            try:
                index = int(segment)
                if index < 0 or index >= len(current):
                    return default
                current = current[index]
            except ValueError:
                return default
        else:
            return default
    return current
```

