import heapq

def topk(items, k):
    if k <= 0:
        return []
    if k >= len(items):
        return sorted(items, reverse=True)

    # Use a min-heap of size k to keep track of the k largest elements
    heap = items[:k]
    heapq.heapify(heap)

    for item in items[k:]:
        if item > heap[0]:
            heapq.heapreplace(heap, item)

    # Return the k largest elements in descending order
    return sorted(heap, reverse=True)
```

