def strip_comments(code):
    lines = code.splitlines()
    result = []
    in_string = False
    string_char = None

    for line in lines:
        new_line = []
        i = 0
        while i < len(line):
            char = line[i]

            if in_string:
                if char == '\\' and i + 1 < len(line):
                    new_line.append(line[i:i+2])
                    i += 2
                    continue
                if char == string_char:
                    in_string = False
                    string_char = None
                new_line.append(char)
            else:
                if char in ('"', "'"):
                    in_string = True
                    string_char = char
                    new_line.append(char)
                elif char == '#':
                    break
                else:
                    new_line.append(char)
            i += 1

        result.append(''.join(new_line))

    return '\n'.join(result)
```

