module.exports = function retryAsync(fn, attempts) {
  return new Promise((resolve, reject) => {
    let currentAttempt = 0;

    const execute = () => {
      currentAttempt++;
      if (currentAttempt > attempts) {
        reject(new Error(`Max attempts (${attempts}) exceeded`));
        return;
      }

      fn()
        .then(result => {
          resolve(result);
        })
        .catch(error => {
          if (currentAttempt < attempts) {
            execute();
          } else {
            reject(error);
          }
        });
    };

    execute();
  });
};

