module.exports = function debounceCount(fn, ms) {
  let timer = null;
  let pending = false;

  const debounced = function () {
    pending = true;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      fn();
      pending = false;
      timer = null;
    }, ms);
  };

  const flush = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    if (pending) {
      fn();
      pending = false;
    }
  };

  return { call: debounced, flush };
};

