function range(start, end, step) {
  if (step === 0) {
    throw new Error("Step cannot be zero");
  }

  const result = [];
  let current = start;

  if (step > 0) {
    while (current < end) {
      result.push(current);
      current += step;
    }
  } else {
    while (current > end) {
      result.push(current);
      current += step;
    }
  }

  return result;
}

module.exports = range;

