module.exports = function throttleManual(fn) {
  let lastCallTime = 0;
  let lastTickTime = 0;
  let isPending = false;

  function call() {
    const now = Date.now();
    if (now - lastTickTime > 0) {
      fn();
      lastCallTime = now;
      isPending = false;
    }
  }

  function tick() {
    lastTickTime = Date.now();
    if (isPending) {
      isPending = false;
      fn();
    }
  }

  return {
    call: call,
    tick: tick
  };
};

