export type Handler = (e: { type: string }) => void;

export class Emitter {
  private listeners: Map<string, Handler[]> = new Map();

  on(t: string, h: Handler): void {
    if (!this.listeners.has(t)) {
      this.listeners.set(t, []);
    }
    this.listeners.get(t)!.push(h);
  }

  emit(t: string): void {
    const handlers = this.listeners.get(t);
    if (handlers) {
      handlers.forEach((h) => h({ type: t }));
    }
  }
}

