export function maxBy<T>(arr: T[], f: (t: T) => number): T | undefined {
  if (arr.length === 0) return undefined;
  let max: T = arr[0];
  let maxIndex = 0;
  for (let i = 1; i < arr.length; i++) {
    if (f(arr[i]) > f(max)) {
      max = arr[i];
      maxIndex = i;
    }
  }
  return max;
