doc-013.text:
Here is a complete implementation example using **Node.js** with **Express** and **Joi** for validation. This example covers all three specified scenarios: successful update (200), validation errors (403), and unauthorized access (403).

### Prerequisites
You will need to install the following dependencies:
```bash
npm install express joi
```

### Implementation Code (`server.js`)

```javascript
const express = require('express');
const Joi = require('joi');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

// Mock Database (In-memory storage)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' }
];

// Validation Schema using Joi
const userUpdateSchema = Joi.object({
  name: Joi.string().min(2).max(50).required(),
  email: Joi.string().email().required()
});

/**
 * PUT /api/v1/users/{id}
 * 
 * Logic:
 * 1. Extract ID from URL params.
 * 2. Validate request body against schema.
 * 3. Check if user exists.
 * 4. Check if the authenticated user (simulated) is the owner.
 * 5. Update and return 200, or return 400/403 as appropriate.
 */
app.put('/api/v1/users/:id', (req, res) => {
  const userId = parseInt(req.params.id);
  const { name, email } = req.body;

  // 1. Validation Error (400)
  const { error } = userUpdateSchema.validate({ name, email });
  if (error) {
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      details: error.details[0].message
    });
  }

  // 2. Check if user exists
  const userIndex = users.findIndex(u => u.id === userId);
  if (userIndex === -1) {
    return res.status(404).json({
      success: false,
      message: 'User not found'
    });
  }

  // 3. Authorization Check (403)
  // Simulating an authenticated user ID from the session/token
  // For this example, let's assume the current user is ID 1 (Alice)
  const currentUserId = 1; 

  if (userId !== currentUserId) {
    return res.status(403).json({
      success: false,
      message: 'Forbidden: You can only edit your own profile.'
    });
  }

  // 4. Update User Data
  users[userIndex].name = name;
  users[userIndex].email = email;

  // 5. Success Response (200)
  res.status(200).json({
    success: true,
    message: 'User updated successfully',
    data: users[userIndex]
  });
});

//

